# 
# This short program tries to find a random 160-digit 
# prime by picking numprimepicks many random odd numbers, until 
# it finds a prime (or fails numprimepics many times). The primality 
# test it uses is a program called newtestp, supplied by another file 
# (day15b.map). 
# 
# Usage: After saving the files day15a.map and day15b.map in the 
#        same directory, run Maple in the same directory, and then say
#
#                 read("day15a.map");
#                 read("day15b.map");
#                 findp(256); 
#
#        (The 256 is the number of trials and can certainly be changed 
#        as you like.)  You'll then either see an error, or a message saying 
#        something about what happened after a number of tries. (There is a 
#        weird glitch that only seems to go away if you load the code twice.) 
#        So if you got the error, just say  
#
#                 read("day15a.map");
#                 read("day15b.map");
#                 findp(256); 
#        
#        again, and then you should get meaningful output. You 
#        can change the 256 to any number of tries you want. You'll see 
#        things slow down if you choose a bigger number, but then 
#        you'll be more likely to find a 160-digit prime... 
findp:=proc(numprimepicks)  

local foundpseudoprime,n,putp,q,randomp: 

with(padic): 

# want a random 160-digit odd number p. this means 
# p is in {10^159+1,...,10^160-1}, or, 2{(10^159)/2,...,(10^160-2)/2}+1
randomp:=2*rand((10^159/2)..((10^160-2)/2))+1:  

foundpseudoprime:=0: n:=numprimepicks: 

while (foundpseudoprime=0 and n>0) do  
 n:=n-1: putp:=randomp(): 
 foundpseudoprime:=newtestp(putp): 
end:

if foundpseudoprime=1 then  
  print(["...after ",numprimepicks-n," tries!"]); 
 else  
  print("Sorry, couldn't find a pseudo-prime after ",numprimepicks," tries.");
end: 

end proc: 
